// src/components/Sidebar.js
import React from 'react';
import { Link, useLocation } from 'react-router-dom';
import './Sidebar.css';

const Sidebar = () => {
  const location = useLocation();
  
  // Check if the current path matches a given path
  const isActive = (path) => {
    return location.pathname === path;
  };
  
  return (
    <div className="sidebar">
      <nav className="sidebar-nav">
        <Link 
          to="/dashboard" 
          className={`sidebar-nav-item ${isActive('/dashboard') ? 'active' : ''}`}
        >
          <i className="icon">📊</i>
          <span>Dashboard</span>
        </Link>
        <Link 
          to="/patient/new" 
          className={`sidebar-nav-item ${isActive('/patient/new') ? 'active' : ''}`}
        >
          <i className="icon">👤</i>
          <span>New Patient</span>
        </Link>
        <Link 
          to="/queue" 
          className={`sidebar-nav-item ${isActive('/queue') ? 'active' : ''}`}
        >
          <i className="icon">🧑‍⚕️</i>
          <span>Patient Queue</span>
        </Link>
      </nav>
      <div className="sidebar-footer">
        <div className="system-status online">
          <span className="status-indicator"></span>
          System Online
        </div>
        <div className="system-version">
          v1.0.0
        </div>
      </div>
    </div>
  );
};

export default Sidebar;
